package com.example;import org.springframework.boot.*;import org.springframework.boot.autoconfigure.*;import org.springframework.cache.annotation.EnableCaching;import org.springframework.context.annotation.Bean;@SpringBootApplication @EnableCaching public class ShopApplication {public static void main(String[] a){SpringApplication.run(ShopApplication.class,a);}@Bean CommandLineRunner seed(ProductRepository r){return args->{r.save(new Product("Laptop",55000));r.save(new Product("Phone",22000));r.save(new Product("Tablet",18000));};}}
